      return ClientAudioInterrupted.fromJson(json);
    case "audioResumed":
      return ClientAudioResumed.fromJson(json);
    case "networkChanged":
      return ClientNetworkChanged.fromJson(json);
    case "permissionState":
      return ClientPermissionState.fromJson(json);
    case "resume":
      return ClientResume.fromJson(json);
    case "signal.offer":
      return ClientSignalOffer.fromJson(json);
    case "signal.answer":
      return ClientSignalAnswer.fromJson(json);
    case "signal.ice":
